// modules/library/pages/AuthorList.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";

export default function AuthorList() {
  const [authors, setAuthors] = useState([]);

  useEffect(() => {
    authorApi.get("/").then((res) => setAuthors(res.data));
  }, []);

  const deleteAuthor = async (id) => {
    if (!window.confirm("Remove this author?")) return;

    await authorApi.delete(`/${id}`);
    setAuthors(authors.filter((a) => a.id !== id));
  };

  return (
    <div className="content-wrapper p-4">

      <h2>Authors</h2>

      <a className="btn btn-primary mb-3" href="/library/author/create">
        + Add Author
      </a>

      <table className="table table-bordered table-hover">
        <thead>
          <tr>
            <th>#</th>
            <th>Name</th>
            <th>Country</th>
            <th>Actions</th>
          </tr>
        </thead>

        <tbody>
          {authors.length ? (
            authors.map((a, i) => (
              <tr key={a.id}>
                <td>{i + 1}</td>
                <td>{a.name}</td>
                <td>{a.country}</td>
                <td>
                  <a className="btn btn-info btn-sm" href={`/library/authors/edit/${a.id}`}>
                    Edit
                  </a>

                  <button
                    className="btn btn-danger btn-sm ms-2"
                    onClick={() => deleteAuthor(a.id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td className="text-center text-muted" colSpan={4}>
                No authors available.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
